    # vertical markers: extend up with band color, down with marker color
    for c in range(w):
        col=[g[r][c] for r in range(h)]
        nz=[r for r in range(h) if col[r]!=0]
        if not nz: continue
        # marker = contiguous nonzero block not part of a long band? treat: if block length <=2 use as marker
        blocks=[]; s=nz[0]; p=nz[0]
        for r in nz[1:]:
            if r==p+1: p=r
            else: blocks.append((s,p)); s=r; p=r
        blocks.append((s,p))
        for (a,b) in blocks:
            if b-a+1<=3:  # marker
                mcol=col[a]
                # find band row above: nearest row above a with nonzero elsewhere
                band=None
                for r in range(a-1,-1,-1):
                    if out[r][c]!=0: band=r; bandcolor=g[r][c]; break
